(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-challenge-p09-10-advanced"]={"id":"unit22-challenge-p09-10-advanced","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"2-2단원 · 3. 시장 대 줄 서기","name":"9~10문단 · 심화 5지선다","level":"심화","desc":"한 문제에 해당 본문 1문단씩 읽어요.","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","parts":[{"name":"U22-24 · 줄 서기의 도덕성에 관한 질문","items":[{"paragraphCount":1,"readingLabel":"9문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 9문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 9문단]\n그렇다면 줄 서기의 도덕성 측면에서는 어떤 주장을 펼칠 수 있을까? 대리 줄 서기와 암표 판매를 금지하려는 이유는 무엇일까? 센트럴 파크에서 열리는 셰익스피어 공연의 대변인은 다음과 같은 근거를 댔다. “대리 줄 서기와 암표 판매는 공원에서 셰익스피어 공연을 간절하게 보고 싶어 하는 사람에게서 좌석과 입장권을 빼앗고 있다. 우리는 사람들이 공연을 무료로 관람하기를 원한다.”","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["순서"],"id":"U22-24-S1","type":"mc","sent":"9문단의 내용과 맞는 설명은?","options":["9문단은 줄 서기가 아니라 가격을 올렸을 때의 효과를 묻는다.","9문단은 대리 줄 서기와 암표 판매를 왜 허용하려 하는지 묻는다.","9문단은 이유를 묻지 않고 줄 서기에 관한 결론만 내린다.","9문단은 줄 서기가 도덕적으로 옳은지 생각해 보게 한다. 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.","9문단 처음의 질문은 극장 대변인이 한 말이다."],"answer":"9문단은 줄 서기가 도덕적으로 옳은지 생각해 보게 한다. 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.","why":"9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","choiceReviews":{"9문단은 줄 서기가 도덕적으로 옳은지 생각해 보게 한다. 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.":{"reason":"9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[]},"9문단은 줄 서기가 아니라 가격을 올렸을 때의 효과를 묻는다.":{"reason":"바르게 고치면: 9문단은 줄 서기가 도덕적으로 옳은지 묻는다.\n9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[{"start":11,"end":30,"before":"아니라 가격을 올렸을 때의 효과를 ","after":"도덕적으로 옳은지 "}]},"9문단은 대리 줄 서기와 암표 판매를 왜 허용하려 하는지 묻는다.":{"reason":"바르게 고치면: 9문단은 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.\n9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[{"start":23,"end":28,"before":"허용하려 ","after":"막으려 "}]},"9문단은 이유를 묻지 않고 줄 서기에 관한 결론만 내린다.":{"reason":"바르게 고치면: 9문단은 줄 서기와 암표 판매에 관한 이유를 묻는다.\n9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[{"start":0,"end":5,"before":"9문단은 ","after":"9문단은 줄 서기와 암표 판매에 관한 "},{"start":9,"end":32,"before":"묻지 않고 줄 서기에 관한 결론만 내린다.","after":"묻는다."}]},"9문단 처음의 질문은 극장 대변인이 한 말이다.":{"reason":"바르게 고치면: 9문단 처음의 질문은 글쓴이가 한 말이다.\n9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[{"start":12,"end":20,"before":"극장 대변인이 ","after":"글쓴이가 "}]}},"pageSpecificReasons":true,"evidence":{"title":"줄 서기의 도덕성에 관한 질문","statement":"9문단은 줄 서기가 도덕적으로 옳은지 생각해 보게 한다. 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.","explanation":"9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","valid":["L09:1","L09:2"],"sources":[{"id":"L09","title":"줄 서기를 돈으로 살 수 있을까","label":"9문단","sentences":[{"id":"L09:1","text":"그렇다면 줄 서기의 도덕성 측면에서는 어떤 주장을 펼칠 수 있을까?","paragraph":0,"memberIds":["L09:1"],"topic":"그럼 이제 반대로, 줄 서기가 옳다고 보는 쪽(줄 서기의 도덕성)에서는 무슨 말을 할 수 있을까?"},{"id":"L09:2","text":"대리 줄 서기와 암표 판매를 금지하려는 이유는 무엇일까?","paragraph":0,"memberIds":["L09:2"],"topic":"대신 줄 서기와 암표를 왜 막으려는 걸까?"},{"id":"L09:3","text":"센트럴 파크에서 열리는 셰익스피어 공연의 대변인은 다음과 같은 근거를 댔다.","paragraph":0,"memberIds":["L09:3"],"topic":"공연 측 대변인(대표로 말하는 사람)은 이렇게 말했다."},{"id":"L09:4","text":"“대리 줄 서기와 암표 판매는 공원에서 셰익스피어 공연을 간절하게 보고 싶어 하는 사람에게서 좌석과 입장권을 빼앗고 있다. 우리는 사람들이 공연을 무료로 관람하기를 원한다.”","paragraph":0,"memberIds":["L09:4","L09:5"],"topic":"\"대신 줄 서기와 암표는 공연을 정말 보고 싶은 사람의 자리를 빼앗는다."}]}]},"editorSourceVersion":"3ac7fa613e52a8d234c3388b4bd449dcb81adf8a78c69da5b9f62300eec34404"}]},{"name":"U22-25 · 대변인의 두 주장","items":[{"paragraphCount":1,"readingLabel":"9문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 9문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 9문단]\n그렇다면 줄 서기의 도덕성 측면에서는 어떤 주장을 펼칠 수 있을까? 대리 줄 서기와 암표 판매를 금지하려는 이유는 무엇일까? 센트럴 파크에서 열리는 셰익스피어 공연의 대변인은 다음과 같은 근거를 댔다. “대리 줄 서기와 암표 판매는 공원에서 셰익스피어 공연을 간절하게 보고 싶어 하는 사람에게서 좌석과 입장권을 빼앗고 있다. 우리는 사람들이 공연을 무료로 관람하기를 원한다.”","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["주체"],"id":"U22-25-S1","type":"mc","sent":"9문단의 내용과 맞는 설명은?","options":["극장 대변인은 암표 덕분에 공연을 꼭 보고 싶은 관객이 표를 얻는다고 본다.","극장 대변인은 사람들이 최고 가격을 내고 공연을 보기를 원한다.","사람들이 무료로 공연을 보게 하려는 사람은 대리 줄 서기 사업자다.","극장 대변인은 암표상에게 표가 돌아가지 않는 것을 걱정한다.","극장 대변인은 대리 줄 서기와 암표 때문에 공연을 꼭 보고 싶은 관객이 표를 빼앗긴다고 본다. 관객들이 무료로 공연을 보기를 원한다."],"answer":"극장 대변인은 대리 줄 서기와 암표 때문에 공연을 꼭 보고 싶은 관객이 표를 빼앗긴다고 본다. 관객들이 무료로 공연을 보기를 원한다.","why":"극장 대변인은 공연을 간절히 원하는 사람에게 표가 돌아가야 한다고 봐요. 대리 줄 서기와 암표가 그 사람들의 자리를 빼앗는다고 말해요.\n9문단에서 확인할 수 있어요.","choiceReviews":{"극장 대변인은 대리 줄 서기와 암표 때문에 공연을 꼭 보고 싶은 관객이 표를 빼앗긴다고 본다. 관객들이 무료로 공연을 보기를 원한다.":{"reason":"극장 대변인은 공연을 간절히 원하는 사람에게 표가 돌아가야 한다고 봐요. 대리 줄 서기와 암표가 그 사람들의 자리를 빼앗는다고 말해요.\n9문단에서 확인할 수 있어요.","edits":[]},"극장 대변인은 암표 덕분에 공연을 꼭 보고 싶은 관객이 표를 얻는다고 본다.":{"reason":"바르게 고치면: 극장 대변인은 암표 때문에 공연을 꼭 보고 싶은 관객이 표를 빼앗긴다고 본다.\n극장 대변인은 공연을 간절히 원하는 사람에게 표가 돌아가야 한다고 봐요. 대리 줄 서기와 암표가 그 사람들의 자리를 빼앗는다고 말해요.\n9문단에서 확인할 수 있어요.","edits":[{"start":11,"end":15,"before":"덕분에 ","after":"때문에 "},{"start":34,"end":39,"before":"얻는다고 ","after":"빼앗긴다고 "}]},"극장 대변인은 사람들이 최고 가격을 내고 공연을 보기를 원한다.":{"reason":"바르게 고치면: 극장 대변인은 사람들이 무료로 공연을 보기를 원한다.\n극장 대변인은 공연을 간절히 원하는 사람에게 표가 돌아가야 한다고 봐요. 대리 줄 서기와 암표가 그 사람들의 자리를 빼앗는다고 말해요.\n9문단에서 확인할 수 있어요.","edits":[{"start":13,"end":23,"before":"최고 가격을 내고 ","after":"무료로 "}]},"사람들이 무료로 공연을 보게 하려는 사람은 대리 줄 서기 사업자다.":{"reason":"바르게 고치면: 사람들이 무료로 공연을 보게 하려는 사람은 극장 대변인이다.\n극장 대변인은 공연을 간절히 원하는 사람에게 표가 돌아가야 한다고 봐요. 대리 줄 서기와 암표가 그 사람들의 자리를 빼앗는다고 말해요.\n9문단에서 확인할 수 있어요.","edits":[{"start":24,"end":37,"before":"대리 줄 서기 사업자다.","after":"극장 대변인이다."}]},"극장 대변인은 암표상에게 표가 돌아가지 않는 것을 걱정한다.":{"reason":"바르게 고치면: 극장 대변인은 공연을 꼭 보고 싶은 관객에게 표가 돌아가지 않는 것을 걱정한다.\n극장 대변인은 공연을 간절히 원하는 사람에게 표가 돌아가야 한다고 봐요. 대리 줄 서기와 암표가 그 사람들의 자리를 빼앗는다고 말해요.\n9문단에서 확인할 수 있어요.","edits":[{"start":8,"end":14,"before":"암표상에게 ","after":"공연을 꼭 보고 싶은 관객에게 "}]}},"pageSpecificReasons":true,"evidence":{"title":"대변인의 두 주장","statement":"극장 대변인은 대리 줄 서기와 암표 때문에 공연을 꼭 보고 싶은 관객이 표를 빼앗긴다고 본다. 관객들이 무료로 공연을 보기를 원한다.","explanation":"극장 대변인은 공연을 간절히 원하는 사람에게 표가 돌아가야 한다고 봐요. 대리 줄 서기와 암표가 그 사람들의 자리를 빼앗는다고 말해요.\n9문단에서 확인할 수 있어요.","valid":["L09:4"],"sources":[{"id":"L09","title":"줄 서기를 돈으로 살 수 있을까","label":"9문단","sentences":[{"id":"L09:1","text":"그렇다면 줄 서기의 도덕성 측면에서는 어떤 주장을 펼칠 수 있을까?","paragraph":0,"memberIds":["L09:1"],"topic":"그럼 이제 반대로, 줄 서기가 옳다고 보는 쪽(줄 서기의 도덕성)에서는 무슨 말을 할 수 있을까?"},{"id":"L09:2","text":"대리 줄 서기와 암표 판매를 금지하려는 이유는 무엇일까?","paragraph":0,"memberIds":["L09:2"],"topic":"대신 줄 서기와 암표를 왜 막으려는 걸까?"},{"id":"L09:3","text":"센트럴 파크에서 열리는 셰익스피어 공연의 대변인은 다음과 같은 근거를 댔다.","paragraph":0,"memberIds":["L09:3"],"topic":"공연 측 대변인(대표로 말하는 사람)은 이렇게 말했다."},{"id":"L09:4","text":"“대리 줄 서기와 암표 판매는 공원에서 셰익스피어 공연을 간절하게 보고 싶어 하는 사람에게서 좌석과 입장권을 빼앗고 있다. 우리는 사람들이 공연을 무료로 관람하기를 원한다.”","paragraph":0,"memberIds":["L09:4","L09:5"],"topic":"\"대신 줄 서기와 암표는 공연을 정말 보고 싶은 사람의 자리를 빼앗는다."}]}]},"editorSourceVersion":"9bf95f4c3e5bf1b6bf3b073f46f0fd8092d150216246c7d646d4147a12553cfd"}]},{"name":"U22-26 · 공정성 주장에 대한 필자의 평가","items":[{"paragraphCount":1,"readingLabel":"10문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 10문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 10문단]\n아마도 대변인의 의도는 암표 거래는 125달러를 지불할 만한 경제적 여유가 없는 사람에게 불공정한 행위라는 것이리라. 보통 사람은 그만큼 불리하게 되어 입장권을 손에 넣기가 더욱 힘들어진다. 이 주장은 설득력이 있다. 돈을 받고 대신 줄을 선 사람이나 암표상이 입장권을 확보했다면 그 뒤에 서 있던 사람, 즉 암표 가격을 지불할 만한 경제적 여유가 없는 사람은 손해를 본다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-26-S1","type":"mc","sent":"10문단의 내용과 맞는 설명은?","options":["글쓴이는 대변인의 말을 돈 없는 관객이 불리해진다는 뜻으로 이해한다. 글쓴이도 그 걱정이 설득력 있다고 본다.","글쓴이는 돈 없는 관객이 불리해진다는 말에 설득력이 없다고 본다.","글쓴이는 대변인이 암표가 돈 없는 관객에게 공정하다고 말한 것으로 이해한다.","글쓴이는 대변인이 가장 비싼 값을 내는 관객을 걱정했다고 이해한다.","'돈이 없는 사람에게 불공정하다'는 말은 대변인이 직접 한 말이다."],"answer":"글쓴이는 대변인의 말을 돈 없는 관객이 불리해진다는 뜻으로 이해한다. 글쓴이도 그 걱정이 설득력 있다고 본다.","why":"필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","choiceReviews":{"글쓴이는 대변인의 말을 돈 없는 관객이 불리해진다는 뜻으로 이해한다. 글쓴이도 그 걱정이 설득력 있다고 본다.":{"reason":"필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[]},"글쓴이는 돈 없는 관객이 불리해진다는 말에 설득력이 없다고 본다.":{"reason":"바르게 고치면: 글쓴이는 돈 없는 관객이 불리해진다는 말에 설득력이 있다고 본다.\n필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[{"start":29,"end":33,"before":"없다고 ","after":"있다고 "}]},"글쓴이는 대변인이 암표가 돈 없는 관객에게 공정하다고 말한 것으로 이해한다.":{"reason":"바르게 고치면: 글쓴이는 대변인이 암표가 돈 없는 관객에게 불공정하다고 말한 것으로 이해한다.\n필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[{"start":24,"end":30,"before":"공정하다고 ","after":"불공정하다고 "}]},"글쓴이는 대변인이 가장 비싼 값을 내는 관객을 걱정했다고 이해한다.":{"reason":"바르게 고치면: 글쓴이는 대변인이 돈이 부족한 관객을 걱정했다고 이해한다.\n필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[{"start":10,"end":22,"before":"가장 비싼 값을 내는 ","after":"돈이 부족한 "}]},"'돈이 없는 사람에게 불공정하다'는 말은 대변인이 직접 한 말이다.":{"reason":"바르게 고치면: '돈이 없는 사람에게 불공정하다'는 말은 글쓴이가 대변인의 말을 풀어서 설명한 것이다.\n필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[{"start":23,"end":37,"before":"대변인이 직접 한 말이다.","after":"글쓴이가 대변인의 말을 풀어서 설명한 것이다."}]}},"pageSpecificReasons":true,"evidence":{"title":"공정성 주장에 대한 필자의 평가","statement":"글쓴이는 대변인의 말을 돈 없는 관객이 불리해진다는 뜻으로 이해한다. 글쓴이도 그 걱정이 설득력 있다고 본다.","explanation":"필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","valid":["L10:3"],"sources":[{"id":"L10","title":"줄 서기를 돈으로 살 수 있을까","label":"10문단","sentences":[{"id":"L10:1","text":"아마도 대변인의 의도는 암표 거래는 125달러를 지불할 만한 경제적 여유가 없는 사람에게 불공정한 행위라는 것이리라.","paragraph":0,"memberIds":["L10:1"],"topic":"대변인이 하고 싶은 말은 아마 이것일 것이다. \"암표는 125달러를 낼 돈이 없는 사람에게 불공평하다.\""},{"id":"L10:2","text":"보통 사람은 그만큼 불리하게 되어 입장권을 손에 넣기가 더욱 힘들어진다.","paragraph":0,"memberIds":["L10:2"],"topic":"평범한 사람은 그만큼 불리해져서 표를 구하기가 더 어려워진다."},{"id":"L10:3","text":"이 주장은 설득력이 있다.","paragraph":0,"memberIds":["L10:3"],"topic":"필자는 “암표 거래는 돈이 부족한 사람에게 불공정하다”는 주장에 설득력이 있다고 본다."},{"id":"L10:4","text":"돈을 받고 대신 줄을 선 사람이나 암표상이 입장권을 확보했다면 그 뒤에 서 있던 사람, 즉 암표 가격을 지불할 만한 경제적 여유가 없는 사람은 손해를 본다.","paragraph":0,"memberIds":["L10:4"],"topic":"줄 알바나 암표상이 앞에서 표를 가져가 버리면, 그 뒤에 선 사람은 표를 못 받는다. 그 사람은 비싼 암표를 살 돈도 없다. 그러니 손해를 본다."}]}]},"editorSourceVersion":"fef777d1ab3a5986f8fc143e00fc66ae18de606344a5249c078b8295f55cac74"}]},{"name":"U22-27 · 암표 확보가 뒤 사람에게 미치는 영향","items":[{"paragraphCount":1,"readingLabel":"10문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 10문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 10문단]\n아마도 대변인의 의도는 암표 거래는 125달러를 지불할 만한 경제적 여유가 없는 사람에게 불공정한 행위라는 것이리라. 보통 사람은 그만큼 불리하게 되어 입장권을 손에 넣기가 더욱 힘들어진다. 이 주장은 설득력이 있다. 돈을 받고 대신 줄을 선 사람이나 암표상이 입장권을 확보했다면 그 뒤에 서 있던 사람, 즉 암표 가격을 지불할 만한 경제적 여유가 없는 사람은 손해를 본다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["인과"],"id":"U22-27-S1","type":"mc","sent":"10문단의 내용과 맞는 설명은?","options":["암표상이 표를 먼저 가져가면, 뒤에서 기다리던 돈 없는 관객은 이익을 얻는다.","암표상이나 대신 줄을 선 사람이 표를 먼저 받아 가면, 뒤에서 기다리던 관객은 무료 표를 못 받을 수 있다. 암표를 살 돈도 없다면 손해를 본다.","글쓴이가 걱정하는 관객은 암표를 살 돈이 충분한 사람이다.","암표상이 표를 한 장도 받지 않아도, 암표상 때문에 뒤의 관객이 받을 표가 줄어든다.","글쓴이가 걱정하는 관객은 암표상보다 먼저 표를 받은 사람이다."],"answer":"암표상이나 대신 줄을 선 사람이 표를 먼저 받아 가면, 뒤에서 기다리던 관객은 무료 표를 못 받을 수 있다. 암표를 살 돈도 없다면 손해를 본다.","why":"암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","choiceReviews":{"암표상이나 대신 줄을 선 사람이 표를 먼저 받아 가면, 뒤에서 기다리던 관객은 무료 표를 못 받을 수 있다. 암표를 살 돈도 없다면 손해를 본다.":{"reason":"암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[]},"암표상이 표를 먼저 가져가면, 뒤에서 기다리던 돈 없는 관객은 이익을 얻는다.":{"reason":"바르게 고치면: 암표상이 표를 먼저 가져가면, 뒤에서 기다리던 돈 없는 관객은 손해를 본다.\n암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[{"start":35,"end":43,"before":"이익을 얻는다.","after":"손해를 본다."}]},"글쓴이가 걱정하는 관객은 암표를 살 돈이 충분한 사람이다.":{"reason":"바르게 고치면: 글쓴이가 걱정하는 관객은 암표를 살 돈이 부족한 사람이다.\n암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[{"start":23,"end":27,"before":"충분한 ","after":"부족한 "}]},"암표상이 표를 한 장도 받지 않아도, 암표상 때문에 뒤의 관객이 받을 표가 줄어든다.":{"reason":"바르게 고치면: 암표상이 표를 먼저 받아 가면, 암표상 때문에 뒤의 관객이 받을 표가 줄어든다.\n암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[{"start":8,"end":21,"before":"한 장도 받지 않아도, ","after":"먼저 받아 가면, "}]},"글쓴이가 걱정하는 관객은 암표상보다 먼저 표를 받은 사람이다.":{"reason":"바르게 고치면: 글쓴이가 걱정하는 관객은 암표상 뒤에서 표를 기다리는 사람이다.\n암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[{"start":14,"end":23,"before":"암표상보다 먼저 ","after":"암표상 뒤에서 "},{"start":26,"end":29,"before":"받은 ","after":"기다리는 "}]}},"pageSpecificReasons":true,"evidence":{"title":"암표 확보가 뒤 사람에게 미치는 영향","statement":"암표상이나 대신 줄을 선 사람이 표를 먼저 받아 가면, 뒤에서 기다리던 관객은 무료 표를 못 받을 수 있다. 암표를 살 돈도 없다면 손해를 본다.","explanation":"암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","valid":["L10:4"],"sources":[{"id":"L10","title":"줄 서기를 돈으로 살 수 있을까","label":"10문단","sentences":[{"id":"L10:1","text":"아마도 대변인의 의도는 암표 거래는 125달러를 지불할 만한 경제적 여유가 없는 사람에게 불공정한 행위라는 것이리라.","paragraph":0,"memberIds":["L10:1"],"topic":"대변인이 하고 싶은 말은 아마 이것일 것이다. \"암표는 125달러를 낼 돈이 없는 사람에게 불공평하다.\""},{"id":"L10:2","text":"보통 사람은 그만큼 불리하게 되어 입장권을 손에 넣기가 더욱 힘들어진다.","paragraph":0,"memberIds":["L10:2"],"topic":"평범한 사람은 그만큼 불리해져서 표를 구하기가 더 어려워진다."},{"id":"L10:3","text":"이 주장은 설득력이 있다.","paragraph":0,"memberIds":["L10:3"],"topic":"필자는 “암표 거래는 돈이 부족한 사람에게 불공정하다”는 주장에 설득력이 있다고 본다."},{"id":"L10:4","text":"돈을 받고 대신 줄을 선 사람이나 암표상이 입장권을 확보했다면 그 뒤에 서 있던 사람, 즉 암표 가격을 지불할 만한 경제적 여유가 없는 사람은 손해를 본다.","paragraph":0,"memberIds":["L10:4"],"topic":"줄 알바나 암표상이 앞에서 표를 가져가 버리면, 그 뒤에 선 사람은 표를 못 받는다. 그 사람은 비싼 암표를 살 돈도 없다. 그러니 손해를 본다."}]}]},"editorSourceVersion":"7969b31b23d75ed638ec852dad3de44ec6bd9b393ca6547228dfa004a729d2e3"}]}],"readingBlock":"challenge","readingChunk":"p09-10","cat":"2-2단원"};})(window);
